class RiskRewardDilemma(ebase):
    """
    Risk-Reward Dilemma.
    """ 

    def __init__(self,
                 pc:float,  # collapse probability
                 pr:float,  # recovery probability
                 rc:float,  # cautious reward
                 rr:float,  # risky reward
                 rd:float,  # reward in degraded state
                 asym=False,  # whether deg state is asymmetric
                 rdr=0.01):  # risky reward in deg state if deg state is asymmmetric
            
        self.N = 1
        self.M = 2
        self.Z = 2

        self.pc = pc
        self.pr = pr
        self.rc = rc
        self.rr = rr
        self.rd = rd
        if asym==True:
            self.rdr = rdr
        else:
            self.rdr = rd
        
        self.disttype = None
        
        self.Aset = self.actions()  # to have them available for the creation
        self.Sset = self.states()   # of the Transition and Reward Tensors

        self.state = 1 # initial state
        
        self.T = self.TransitionTensor()
        self.R = self.RewardTensor()
        self.F = np.array(self.FinalStates())
        # super().__init__()

