@patch
def TransitionTensor(self:RiskRewardDilemma):
    """Get the Transition Tensor."""
    dim = np.concatenate(([self.Z],
                          [self.M for _ in range(self.N)],
                          [self.Z]))
    Tsas = np.ones(dim) * (-1)

    for index, _ in np.ndenumerate(Tsas):
        Tsas[index] = self._transition_probability(index[0],
                                                   index[1],
                                                   index[2])
    return Tsas

@patch
def _transition_probability(self:RiskRewardDilemma,
                            s:int, # the state index
                            a:int, # index for action
                            s_:int  # the next-state index
                           ) -> float:  # transition probability 
    """
    Returns the transition probability for current state `s`, joint action `jA`, and next state `s_`.
    """
    transitionprob = 0

    if self.Sset[s] == 'p': # if we are in the prosperous state
        # determine the agent's choice
        choice = self.Aset[a]          
        if choice == 'c':  # cautious
            transitionprob = 0
        else:  # risky
            transitionprob = self.pc
            
        if self.Sset[s_] == 'd': # if we transitioned to the degraded state
            return transitionprob  # that is our transition probability
        else:  # back to the prosperous state
            return 1 - transitionprob
    
    else:  # if we are in the degraded state
        # determine the agent's choice
        choice = self.Aset[a]
        if choice == 'c':  # cautious
            transitionprob = self.pr
        else:  # risky
            transitionprob = 0
            
        if self.Sset[s_] == 'p': # if we transitioned to the prosperous state
            return transitionprob  # that is our transition probability
        else:  # back to the prosperous state
            return 1 - transitionprob

# %% ../../nbs/03.03_RiskRewardDilemma.ipynb #04157f52
@patch
def RewardTensor(self:RiskRewardDilemma):
    """Get the Reward Tensor R[i,s,a1,...,aN,s']."""
    dim = np.concatenate(([self.N],
                          [self.Z],
                          [self.M],
                          [self.Z]))
    Risas = np.zeros(dim)

    for index, _ in np.ndenumerate(Risas):
        Risas[index] = self._reward(index[0], index[1], index[2],
                                    index[3])
    return Risas

@patch
def _reward(self:RiskRewardDilemma,
            i:int, # the agent index
            s:int, # the state index
            a:int, # the action index
            s_:int  # the next-state index
            ) -> float:  # reward value
    """
    Returns the reward value for agent `i` in current state `s`, under joint action `jA`, when transitioning to next state `s_`.
    """
    if self.Sset[s] == 'd' or self.Sset[s_] == 'd':  # if either current or next state is degraded
        # determine the agent's choice
        choice = self.Aset[a]  
        if choice == 'c':  # cautious
            reward = self.rd
        else:  # risky
            reward = self.rdr
        return reward 
    
    else:  # if current and next state are prosperous
        # determine the agent's choice
        choice = self.Aset[a]          
        if choice == 'c':  # cautious
            reward = self.rc
        else:  # risky
            reward = self.rr
        return reward

